#include "rom_kernel.h"
#include <string.h>
#define A(x) (TF_RAM_BASE+UINT32_C(x))
#define HOPS (TF_RAM_SIZE+1u)
static int stop(rk_model *m,uint32_t va,uint32_t address){m->flow=RK_HALT;m->unknown_va=va;m->unknown_address=address;if(m->memory){m->memory->unknown_effects++;m->memory->last_unknown_va=va;m->memory->last_unknown_address=address;}return 0;}
static int begin(rk_model *m){if(!m||!m->memory||!m->candidate)return 0;++m->operations;if(m->candidate->profile!=RC_WCH_64BE955_V130)return stop(m,0,0);if(m->candidate->fault)return stop(m,m->candidate->last_unknown_va,m->candidate->last_unknown_address);return m->flow==RK_RETURNED;}
static int span(rk_model *m,uint32_t p,unsigned n,uint32_t va){return p>=TF_RAM_BASE&&n<=TF_RAM_SIZE&&p-TF_RAM_BASE<=TF_RAM_SIZE-n?1:stop(m,va,p);}
static int read(rk_model *m,uint32_t p,unsigned n,uint32_t va,uint32_t *out){unsigned i;uint32_t v=0;if(!span(m,p,n,va))return 0;for(i=0;i<n;i++){if(m->memory->known[p-TF_RAM_BASE+i]!=255)return stop(m,va,p+i);v|=(uint32_t)m->memory->ram[p-TF_RAM_BASE+i]<<(8*i);}*out=v;return 1;}
static int write(rk_model *m,uint32_t p,unsigned n,uint32_t v,uint32_t va){unsigned i;if(!span(m,p,n,va))return 0;for(i=0;i<n;i++){m->memory->ram[p-TF_RAM_BASE+i]=(uint8_t)(v>>(8*i));m->memory->known[p-TF_RAM_BASE+i]=255;}return 1;}
static int invoke(rk_model *m,rk_kind kind,uint32_t va,uint32_t target,unsigned width,const uint32_t *args,unsigned count,rk_result *out){rk_request r;rk_result v;rk_flow flow;memset(&r,0,sizeof(r));memset(&v,0,sizeof(v));r.kind=kind;r.callsite=va;r.target=target;r.width=width;r.count=count;if(count)memcpy(r.arguments,args,count*sizeof(uint32_t));m->last_request=r;if(!m->backend.invoke)return stop(m,va,target);flow=m->backend.invoke(m->backend.context,m,&r,&v);if(flow!=RK_RETURNED){if(flow==RK_TRANSFER)m->flow=flow;else stop(m,va,target);return 0;}if(out)*out=v;return 1;}
static int indirect(rk_model *m,uint32_t va,uint32_t fn,const uint32_t *args,unsigned count){++m->callbacks;return invoke(m,RK_NATIVE_CALL,va,fn,0,args,count,NULL);}
static int lock(rk_model *m,uint32_t va,uint32_t *saved){rk_result r;uint32_t zero=0;uint32_t store=va==0x2000029c?0x200002a2:va+4;uint32_t fence=va==0x2000029c?0x200002a6:va+8;if(!invoke(m,RK_MMIO_READ,va,0x4002420c,4,NULL,0,&r))return 0;if(r.known!=UINT32_MAX)return stop(m,va,0x4002420c);*saved=r.value;return invoke(m,RK_MMIO_WRITE,store,0x4002420c,4,&zero,1,NULL)&&invoke(m,RK_FENCE_I,fence,0,0,NULL,0,NULL);}
static int restore(rk_model *m,uint32_t saved,uint32_t va){return invoke(m,RK_MMIO_WRITE,va,0x4002420c,4,&saved,1,NULL);}
static int adapter_failure(rk_model *m){return stop(m,m->candidate->last_unknown_va,m->candidate->last_unknown_address);}
static int append(rk_model *m,uint32_t p){uint32_t head,next;unsigned count=0;if(!write(m,p-8,4,0,0x2000021c)||!read(m,A(0x3048),4,0x20000220,&head))return 0;if(!head)return write(m,A(0x3048),4,p,0x20000224);for(;;){if(++count>HOPS)return stop(m,0x2000022a,head);if(!read(m,head-8,4,0x2000022a,&next))return 0;if(!next)return write(m,head-8,4,p,0x20000230);head=next;}}
static int unlink(rk_model *m,uint32_t p,uint32_t previous){uint32_t head,next;if(!read(m,A(0x3048),4,0x4304c,&head)||!read(m,p-8,4,0x4304e,&next))return 0;if(head==p){if(!write(m,A(0x3048),4,next,0x43056))return 0;}else if(!write(m,previous-8,4,next,0x43064))return 0;return write(m,p-8,4,0,0x4305a)&&write(m,p-2,1,255,0x4305e);}
int rk_attach(rk_model *m,rc_adapter *a,const rk_backend *b){memset(m,0,sizeof(*m));m->candidate=a;if(a)m->memory=a->memory;if(b)m->backend=*b;m->flow=RK_RETURNED;if(!a||!a->memory||a->profile!=RC_WCH_64BE955_V130){m->flow=RK_HALT;return 0;}return 1;}
void rk_resume(rk_model *m){m->flow=RK_RETURNED;m->unknown_va=m->unknown_address=0;}
rk_flow rk_queue_reset(rk_model *m){if(begin(m))(void)write(m,A(0x3048),4,0,0x4314e);return m->flow;}
rk_flow rk_msg_send_register(rk_model *m,uint32_t task,uint32_t p,uint32_t *out){uint32_t saved,count,next,owner,status;if(!begin(m)||!lock(m,0x430c6,&saved))return m->flow;if(!p){if(restore(m,saved,0x430d4))*out=5;return m->flow;}if(!read(m,A(0x304d),1,0x430e0,&count))return m->flow;if(task>=count||task<=2){if(!rc_msg_deallocate(m->candidate,p,&status)){adapter_failure(m);return m->flow;}if(restore(m,saved,0x430f8))*out=3;return m->flow;}if(!read(m,p-8,4,0x4310a,&next))return m->flow;if(next){if(!rc_msg_deallocate(m->candidate,p,&status)){adapter_failure(m);return m->flow;}if(restore(m,saved,0x43122))*out=5;return m->flow;}if(!read(m,p-2,1,0x43110,&owner))return m->flow;if(owner!=255){if(!rc_msg_deallocate(m->candidate,p,&status)){adapter_failure(m);return m->flow;}if(restore(m,saved,0x43122))*out=5;return m->flow;}if(!write(m,p-2,1,task,0x4312c)||!append(m,p))return m->flow;if(!rc_set_event(m->candidate,task,0x8000,&status)){adapter_failure(m);return m->flow;}if(restore(m,saved,0x43144))*out=0;return m->flow;}
rk_flow rk_msg_send(rk_model *m,uint8_t task,uint32_t p,uint32_t *out){return rk_msg_send_register(m,task,p,out);}
rk_flow rk_msg_receive_register(rk_model *m,uint32_t task,uint32_t *out){uint32_t saved,current,first=0,previous=0,owner,status;unsigned hops=0;if(!begin(m)||!lock(m,0x2000029c,&saved)||!read(m,A(0x3048),4,0x200002ae,&current))return m->flow;while(current){if(++hops>HOPS){stop(m,0x200002c8,current);return m->flow;}if(!read(m,current-2,1,0x200002c8,&owner))return m->flow;if(owner==task){if(first)break;first=current;}else if(!first)previous=current;if(!read(m,current-8,4,0x2000030a,&current))return m->flow;}if(first&&!unlink(m,first,previous))return m->flow;if(current){if(!rc_set_event(m->candidate,task,0x8000,&status)){adapter_failure(m);return m->flow;}}else if(!rc_timer_stop(m->candidate,task,0x8000,&status)){adapter_failure(m);return m->flow;}if(restore(m,saved,0x200002f6))*out=first;return m->flow;}
rk_flow rk_msg_receive(rk_model *m,uint8_t task,uint32_t *out){return rk_msg_receive_register(m,task,out);}
rk_flow rk_internal_message_dispatch(rk_model *m,uint8_t task,uint16_t events,uint16_t *out){unsigned i;uint32_t p,status,base,selected,callback,argument;if(!begin(m))return m->flow;if(events&0x8000){if(rk_msg_receive(m,task,&p)!=RK_RETURNED)return m->flow;if(p&&!rc_msg_deallocate(m->candidate,p,&status)){adapter_failure(m);return m->flow;}*out=(uint16_t)(events^0x8000);return m->flow;}if(!events){*out=0;return m->flow;}for(i=0;i<16;i++)if(events&(1u<<i)){if(!read(m,A(0x30dc),4,0x43228,&base))return m->flow;selected=base+12u*(16u*task+i);if(!read(m,selected,4,0x43238,&callback)||!read(m,selected+4,4,0x4323c,&argument)||!indirect(m,0x43240,callback,&argument,1)||!write(m,selected,4,0,0x43242)||!write(m,selected+4,4,0,0x43246))return m->flow;*out=(uint16_t)(events^(1u<<i));return m->flow;}*out=events;return m->flow;}
rk_flow rk_internal_dispatch(rk_model *m,uint8_t task,uint16_t events,uint16_t *out){unsigned i;uint32_t base,selected,callback,argument,flag;if(!begin(m))return m->flow;if(!events){*out=0;return m->flow;}for(i=0;i<16;i++)if(events&(1u<<i)){if(!read(m,A(0x30dc),4,0x4317c,&base))return m->flow;selected=base+12u*(16u*task+i);if(!read(m,selected,4,0x4318e,&callback))return m->flow;if(callback){if(!read(m,selected+4,4,0x43194,&argument)||!indirect(m,0x4319a,callback,&argument,1))return m->flow;}if(!read(m,A(0x30dc),4,0x431a4,&base)||!read(m,base+12u*i+8,4,0x431aa,&flag))return m->flow;/* Native rereads task0 flag even for other task IDs. */if(!flag&&(!write(m,selected,4,0,0x431ae)||!write(m,selected+4,4,0,0x431b2)))return m->flow;*out=(uint16_t)(events^(1u<<i));return m->flow;}*out=events;return m->flow;}
static rk_flow idle(rk_model *m){uint32_t flag,phase,token,modulus,base,count,event,index;if(!read(m,A(0x33cd),1,0x20000858,&flag))return m->flow;if(flag){if(!read(m,A(0x33cb),1,0x20000960,&phase))return m->flow;if(!phase){if(!write(m,A(0x33cd),1,0,0x2000096a)||!indirect(m,0x20000972,0x63c72,NULL,0))return m->flow;}}if(!read(m,A(0x3090),4,0x20000866,&token))return m->flow;if(!token)return m->flow;if(!read(m,A(0x30e8),4,0x2000086c,&modulus)||!write(m,A(0x305c),4,modulus,0x2000086e))return m->flow;if(!rc_timer_pump(m->candidate)){adapter_failure(m);return m->flow;}if(!read(m,A(0x30c4),4,0x20000878,&token))return m->flow;if(!token)return m->flow;if(!read(m,A(0x33cb),1,0x2000087e,&phase))return m->flow;if(phase>4)return m->flow;if(!read(m,A(0x341c),1,0x2000088e,&flag))return m->flow;if(flag&4)return m->flow;if(!read(m,A(0x2dac),1,0x20000898,&flag))return m->flow;if(flag)return m->flow;if(!read(m,A(0x304d),1,0x200008a2,&count)||!read(m,A(0x3094),4,0x200008a6,&base))return m->flow;for(index=0;index<count;index++){if(!read(m,base+2u*index,2,0x2000097e,&event))return m->flow;if(event)return m->flow;}(void)indirect(m,0x200008be,0x2000061a,NULL,0);return m->flow;}
rk_flow rk_system_process(rk_model *m){uint32_t irq_mode,flag,phase,callback,base,count,cursor,events,handlers,old,suppression;unsigned hops=0;uint32_t args[2];rk_result result;uint16_t local;if(!begin(m)||!read(m,A(0x30f0),1,0x200007e8,&irq_mode))return m->flow;if(!irq_mode){if(!read(m,A(0x33c9),1,0x20000800,&flag))return m->flow;if(flag&1){if(!read(m,A(0x33cb),1,0x20000806,&phase))return m->flow;if(phase==6||phase==7){if(!write(m,A(0x33c9),1,0,phase==6?0x2000080e:0x200008c8)||!indirect(m,phase==6?0x20000812:0x200008cc,0x200024c6,NULL,0)||!read(m,phase==6?A(0x3084):A(0x3088),4,phase==6?0x20000816:0x200008d0,&callback)||!indirect(m,0x20000818,callback,NULL,0))return m->flow;}}}if(!read(m,A(0x3080),4,0x2000081a,&callback))return m->flow;if(callback&&!indirect(m,0x2000081e,callback,NULL,0))return m->flow;if(!read(m,A(0x3094),4,0x2000082c,&base)||!read(m,A(0x304d),1,0x20000830,&count))return m->flow;for(;;){if(++hops>256){stop(m,0x20000836,A(0x304c));return m->flow;}if(!read(m,A(0x304c),1,0x20000836,&cursor)||!read(m,base+2u*cursor,2,0x20000840,&events))return m->flow;if(events)break;cursor=(uint8_t)(cursor+1u);if(!write(m,A(0x304c),1,cursor,0x200008da))return m->flow;if(cursor>=count)break;}if(!read(m,A(0x304c),1,0x20000844,&cursor))return m->flow;if(cursor>=count){if(!write(m,A(0x304c),1,0,0x2000084c))return m->flow;return idle(m);}if(!read(m,base+2u*cursor,2,0x200008e8,&events)||!write(m,base+2u*cursor,2,0,0x200008ea)||!read(m,A(0x304c),1,0x200008ee,&cursor)||!read(m,A(0x3074),4,0x200008f6,&handlers)||!read(m,handlers+4u*cursor,4,0x20000904,&callback)||!write(m,A(0x308c),2,0,0x20000906))return m->flow;args[0]=cursor;args[1]=events;++m->handlers;if(callback==0x43154){if(rk_internal_dispatch(m,(uint8_t)cursor,(uint16_t)events,&local)!=RK_RETURNED)return m->flow;result.value=local;result.known=UINT32_MAX;}else if(callback==0x431d6){if(rk_internal_message_dispatch(m,(uint8_t)cursor,(uint16_t)events,&local)!=RK_RETURNED)return m->flow;result.value=local;result.known=UINT32_MAX;}else if(!invoke(m,RK_TASK_HANDLER,0x2000090a,callback,0,args,2,&result))return m->flow;if((result.known&65535)!=65535){stop(m,0x2000090a,callback);return m->flow;}if(!read(m,A(0x308c),2,0x2000090c,&suppression)||!read(m,A(0x304c),1,0x20000910,&cursor)||!read(m,A(0x3094),4,0x2000091e,&base)||!read(m,base+2u*cursor,2,0x20000924,&old)||!write(m,base+2u*cursor,2,(result.value&~suppression)|old,0x20000928))return m->flow;if(!read(m,A(0x304c),1,0x2000092a,&cursor))return m->flow;if(cursor&&!write(m,A(0x304c),1,(uint8_t)(cursor+1u),0x20000932))return m->flow;if(!read(m,A(0x3078),4,0x20000936,&callback))return m->flow;if(callback&&(!indirect(m,0x2000093c,callback,NULL,0)||!write(m,A(0x3078),4,0,0x2000093e)))return m->flow;if(!read(m,A(0x304c),1,0x20000942,&cursor)||!read(m,A(0x304d),1,0x20000946,&count))return m->flow;if(cursor>=count){if(!write(m,A(0x304c),1,0,0x2000084c))return m->flow;return idle(m);}return m->flow;}
